    ('margherita', 'Margherita', 'Tomate, muçarela e manjericão.', 39.90, 57.90),
    ('calabresa', 'Calabresa', 'Calabresa, cebola e muçarela.', 42.90, 61.90),
    ('quatro-queijos', 'Quatro Queijos', 'Muçarela, provolone, parmesão e gorgonzola.', 46.90, 66.90),
    ('portuguesa', 'Portuguesa', 'Presunto, ovos, cebola, azeitona e muçarela.', 45.90, 65.90),
    ('frango-catupiry', 'Frango com Catupiry', 'Frango desfiado e requeijão cremoso.', 46.90, 67.90),
    ('pepperoni', 'Pepperoni', 'Pepperoni e muçarela.', 47.90, 68.90),
